// 1. แยกแยะเงื่อนไขเบื้องต้นจากอีเมลที่ได้รับผ่าน IMAP
const item = $input.item.json;
const subject = (item.subject || '').trim();
const inReplyTo = item.headers?.['in-reply-to'] || '';
const references = item.headers?.references || '';
const senderEmail = item.from?.value?.[0]?.address || item.from?.text || '';

// ค้นหา Prefix ที่กำหนด เช่น [PorInsurance] หรือ ข้อความคำนวณค่ากรมธรรม์
let prefixes = [
  '[porinsurance]',
  'ข้อมูลจำนวนพนักงานในบริษัทสำหรับการคำณวนค่ากรมธรรม์',
  '[แจ้งเตือนครบกำหนด]'
];

try {
  const configPrefixes = $('Global Forward Config').item.json.subject_prefixes;
  if (configPrefixes) {
    prefixes = configPrefixes.split(',').map(p => p.trim().toLowerCase());
  }
} catch (e) {}

const lowerSubject = subject.toLowerCase();
const matchedPrefix = prefixes.find(p => p && lowerSubject.includes(p));
const isPrefixMatch = Boolean(matchedPrefix);

// ตรวจสอบว่ามีค่า Header สำหรับ Reply หรือไม่
const isReplyEmail = Boolean(inReplyTo || references || lowerSubject.startsWith('re:'));

// ทำความสะอาด In-Reply-To ID (ตัด < > ออกเพื่อไปค้นใน SQLite)
const cleanReplyId = inReplyTo.replace(/[<>]/g, '').trim();

// ถ้าไม่เข้าทั้ง 2 เงื่อนไข (ไม่ใช่ทั้ง Reply และไม่มี Prefix) ให้หยุดทำงาน
if (!isPrefixMatch && !isReplyEmail) {
  return [];
}

return {
  json: {
    ...item,
    sender_email_clean: senderEmail,
    in_reply_to_clean: cleanReplyId,
    is_prefix_match: isPrefixMatch,
    is_reply_email: isReplyEmail,
    matched_prefix: matchedPrefix || '',
    original_subject: subject
  },
  binary: $input.item.binary || {}
};

// รวมข้อมูลอีเมลต้นฉบับเข้ากับข้อมูลลูกค้าที่พบใน SQLite (ถ้ามี)
const preFilter = $('Pre-Filter: Check Prefix & Reply Headers').item;
const mail = preFilter.json;
const binaryData = preFilter.binary || {};
const sqliteRow = $input.item.json;

const hasSqliteMatch = Boolean(sqliteRow && sqliteRow.id && sqliteRow.email);
const isPrefixMatch = mail.is_prefix_match;

// ถ้าไม่มีทั้งใน SQLite และ Subject ไม่ได้ Match Prefix ให้ข้าม
if (!hasSqliteMatch && !isPrefixMatch) {
  return [];
}

let matchReason = '';
if (hasSqliteMatch && isPrefixMatch) {
  matchReason = `ตรวจพบทั้งใน SQLite (รหัส: ${sqliteRow.no || sqliteRow.id}) และตรงกับ Prefix "${mail.matched_prefix}"`;
} else if (hasSqliteMatch) {
  matchReason = `Reply ตรงกับ mail_id ใน SQLite (ลูกค้า: ${sqliteRow.name})`;
} else {
  matchReason = `ตรงกับเงื่อนไข Subject Prefix: "${mail.matched_prefix}"`;
}

const originalFrom = mail.from?.text || mail.from?.value?.[0]?.address || mail.from || 'Unknown Sender';
const originalSubject = mail.original_subject || mail.subject || 'No Subject';
const originalDate = mail.date || new Date().toISOString();
const originalBody = mail.html || `<pre style="white-space: pre-wrap; font-family: inherit;">${mail.text || '(ไม่มีข้อความ)'}</pre>`;

const targetEmail = $('Global Forward Config').item.json.target_forward_email || 'target-team@yourdomain.com';
const forwardSubject = originalSubject.toLowerCase().startsWith('fwd:') ? originalSubject : `Fwd: ${originalSubject}`;

// สรุปข้อมูลลูกค้าจาก SQLite ถ้าพบ
let customerBox = '';
if (hasSqliteMatch) {
  customerBox = `
  <div style="background-color: #f0fdf4; border: 1px solid #86efac; border-radius: 6px; padding: 12px 16px; margin-bottom: 20px; font-size: 13px;">
    <h4 style="margin: 0 0 8px 0; color: #166534;">👤 ข้อมูลลูกค้าจากฐานข้อมูล SQLite:</h4>
    <p style="margin: 2px 0;"><strong>ชื่อลูกค้า:</strong> ${sqliteRow.name}</p>
    <p style="margin: 2px 0;"><strong>อีเมล:</strong> ${sqliteRow.email}</p>
    <p style="margin: 2px 0;"><strong>สถานะกรมธรรม์:</strong> ${sqliteRow.insurance_status || '-'}</p>
    <p style="margin: 2px 0;"><strong>วันสิ้นสุดกรมธรรม์:</strong> ${sqliteRow.insurance_date_to || '-'}</p>
  </div>
  `;
}

const binaryKeys = Object.keys(binaryData);
const attachmentNotice = binaryKeys.length > 0 
  ? `<p style="color: #0d652d; margin: 4px 0;"><strong>📎 แนบไฟล์จากผู้ส่ง:</strong> ${binaryKeys.length} ไฟล์ (${binaryKeys.join(', ')})</p>` 
  : '';

const forwardHtml = `
<div style="font-family: Arial, sans-serif; font-size: 14px; line-height: 1.6; color: #222;">
  <div style="background-color: #e8f0fe; border-left: 4px solid #1a73e8; padding: 12px 16px; margin-bottom: 20px;">
    <strong>🚀 [Auto-Forwarded by n8n Listener Flow]</strong><br/>
    <span>เงื่อนไขที่ตรวจพบ: <code>${matchReason}</code></span>
  </div>

  ${customerBox}

  <div style="background-color: #f8f9fa; border: 1px solid #ddd; padding: 12px 16px; margin-bottom: 20px; font-size: 13px;">
    <p style="margin: 2px 0;"><strong>From:</strong> ${originalFrom}</p>
    <p style="margin: 2px 0;"><strong>Date:</strong> ${originalDate}</p>
    <p style="margin: 2px 0;"><strong>Subject:</strong> ${originalSubject}</p>
    ${mail.in_reply_to_clean ? `<p style="margin: 2px 0;"><strong>In-Reply-To:</strong> ${mail.in_reply_to_clean}</p>` : ''}
    ${attachmentNotice}
  </div>

  <div style="margin-top: 20px;">
    ${originalBody}
  </div>
</div>
`;

return {
  json: {
    forward_to: targetEmail,
    forward_subject: forwardSubject,
    forward_html: forwardHtml,
    customer_id: sqliteRow.id || null,
    original_from: originalFrom,
    matched_reason: matchReason
  },
  binary: binaryData
};
